import React from 'react';

function Visualizations() {
  return (
    <div className="container mt-5" style={{ marginTop: '1rem' }}>
      <h2>Training Visualizations</h2>
      <div className='row'>
        <div className='col-md-6'>
          <img src='/Train_val_acc.png' alt='Acc' className='visualization'/>
        </div>
        <div className='col-md-6'>
          <img src='/Train_val_loss.png' alt='Loss' className='visualization'/>
        </div>
        {/* You can add charts, graphs, etc. here */}
      </div>
    </div>
  );
}

export default Visualizations;
